const EGG_DO = 'Find all three words on one carton, plus a certifier’s pasture seal.';
const EGG_WATCH_ORDER = [0, 12, 1, 11, 3, 4, 2, 5, 6, 10, 7, 8, 9, 13, 14, 15, 16];
