// Decision-first — unit tests. NO network, NO model.
//
// Every topic opens with the DECISION and a one-line WHY, and the sourced depth sits
// one tap behind it. These pin the inversion so it cannot decay back into an essay:
// the budget that keeps the default view readable in about five seconds, the voice
// rules that apply to every line Kristy speaks, and the claim lock, which did NOT
// widen to accommodate two new fields.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';

import { perimeterKb, questionEntries, publicEntry, sanitizeForModel, buildAnswerInput, sectionIndex } from './perimeter.js';

const entries = nonEmpty(questionEntries(perimeterKb.entries || []), 'questionEntries');

/* ── Every topic leads with a call ─────────────────────────────────────────────── */

test('every entry carries a decision and a one-line why', () => {
  for (const e of entries) {
    assert.ok(typeof e.decision === 'string' && e.decision.trim(), `${e.id} has no decision`);
    assert.ok(typeof e.why === 'string' && e.why.trim(), `${e.id} has no why`);
  }
});

test('the decision is glanceable and the why is one line', () => {
  // The word budget IS the feature. A default view longer than this is the essay
  // coming back in, and in a store nobody reads the essay.
  for (const e of entries) {
    assert.ok(e.decision.length <= 90, `${e.id}: decision is ${e.decision.length} chars — too long to glance`);
    assert.ok(e.why.length <= 120, `${e.id}: why is ${e.why.length} chars — that is a paragraph`);
    // A call, not a discussion. Two sentences at most.
    const sentences = e.decision.split(/[.!?]+\s/).filter(Boolean).length;
    assert.ok(sentences <= 3, `${e.id}: decision runs ${sentences} sentences`);
  }
});

test('the default view stays inside the five-second budget', () => {
  // What renders before any tap: decision + why + the first three buying tips.
  const WORDS = (s) => String(s).trim().split(/\s+/).length;
  for (const e of entries) {
    const above = WORDS(e.decision) + WORDS(e.why) + (e.buying_tips || []).slice(0, 3).reduce((n, t) => n + WORDS(t), 0);
    assert.ok(above <= 90, `${e.id}: ${above} words above the fold`);
  }
});

/* ── The voice, on the two new lines ───────────────────────────────────────────── */

test('no first person anywhere in a decision or a why (VOICE_SPEC)', () => {
  // Kristy is a standard, not a person narrating. The decision is the flattest,
  // most quotable copy in the product, so it is the easiest place for an "I'd" to
  // creep back in.
  const FIRST_PERSON = /\b(i|i'?m|i'?ll|i'?d|i'?ve|me|my|mine|myself|let me)\b/i;
  for (const e of entries) {
    assert.doesNotMatch(e.decision, FIRST_PERSON, `${e.id} decision speaks in first person`);
});

/* ── The counter fills the cart ────────────────────────────────────────────────── */

test('a shortcut answer can become a cart item in the same tap-and-tap', () => {
  // Tap the shortcut, tap the pick. Where an entry resolves to one honest grocery,
  // that pick is on the decision card itself — not under the depth.
  const withPicks = sectionIndex()
    .flatMap((s) => s.shortcuts)
    .map((sc) => publicEntry(entryById(sc.id)))
    .filter((e) => e.cart_pick);
  assert.ok(withPicks.length >= 6, `only ${withPicks.length} surfaced questions resolve to a grocery`);
  for (const e of withPicks) {
    assert.equal(typeof e.cart_pick, 'string');
    assert.doesNotMatch(e.cart_pick.replace(/^100% /, ''), /[$£€%]/, `${e.id} pick carries a price`);
  }
});

test('every counter still offers something to add, and the label section still does not', () => {
  for (const id of ['produce', 'meat', 'seafood', 'eggs_dairy', 'bulk_pantry']) {
    assert.ok(sectionById(id).topics.some((t) => t.cart_pick), `${id} offers nothing to add`);
// docs/api-shapes.generated.md is a BUILD PRODUCT of the route handlers, and this is the only
// thing holding them together.
//
// SWIFT-SPEC.md §A listed paths and methods and no response shapes, which was the biggest gap
// for anyone starting the Swift client cold. Hand-writing ~40 Codable structs against a server
// that changes weekly produces a document that is wrong within a fortnight — a comment
// asserting an invariant, at document scale. So the shapes are derived from the handlers, and
// this test fails when the committed file and the source disagree.
//
// Same arrangement as docs/do-lines-review.md → lib/doLines.json, for the same reason: a
// generated file that nothing checks is a file that drifts. Edit a handler, run
// `node server/scripts/buildApiShapes.js`, commit both.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { nonEmpty } from './testGuards.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SERVER = join(__dirname, '..');
const DOC = join(SERVER, '..', 'docs', 'api-shapes.generated.md');

const doc = readFileSync(DOC, 'utf8');

test('the generated shapes file is not stale', () => {
  // --check re-derives from the handlers and exits 1 on any difference, so this asserts the
  // committed file IS what the current source produces — not merely that it exists.
  try {
    execFileSync(process.execPath, [join(SERVER, 'scripts', 'buildApiShapes.js'), '--check'], {
      cwd: SERVER,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (err) {
    assert.fail(
      'docs/api-shapes.generated.md is stale — a route response changed and the file was not ' +
        'regenerated. Run: node server/scripts/buildApiShapes.js\n' +
        (err.stderr || err.stdout || err.message)
    );
  }
});

test('it covers every route file that mounts handlers', () => {
  // A route file the generator stopped seeing would silently drop its endpoints from the spec.
  const sections = nonEmpty([...doc.matchAll(/^## ([a-z0-9]+\.js)$/gm)].map((m) => m[1]), 'route file sections', 15);
  for (const f of ['list.js', 'counter.js', 'verdict.js', 'scan.js', 'trips.js', 'guest.js', 'subscription.js']) {
    assert.ok(sections.includes(f), `${f} is missing from the generated shapes — did the route regex drift?`);
  }
});

test('it carries the honesty caveat and a hand-check list', () => {
  // The value of this document is that it distinguishes what was derived from what was guessed.
  // Strip either and it becomes a confident fabrication, which is worse than no document.
  assert.match(doc, /NEEDS HAND-CHECK/);
  assert.match(doc, /Request bodies are NOT derived/);
  const listed = [...doc.matchAll(/^- `(GET|POST|PUT|PATCH|DELETE) /gm)];
  assert.ok(listed.length >= 10, `only ${listed.length} hand-check entries — the section looks empty`);
});

test('every handler is either derived or listed as needing a hand-check', () => {
  // No third category. A handler that is neither would be a shape a reader trusts by default
  // and nobody verified.
  const m = doc.match(/_(\d+) handlers, (\d+) literal responses derived\._/);
  assert.ok(m, 'the summary footer is missing — the generator changed shape');
  const handlers = Number(m[1]);
  const handCheck = Number((doc.match(/^(\d+) of (\d+) handlers have at least one/m) || [])[1] || 0);
  assert.ok(handlers > 40, `only ${handlers} handlers found; the route regex has drifted`);
  assert.ok(handCheck > 0, 'zero hand-checks reported — implausible, and it would mean the flagging broke');
  assert.ok(handCheck <= handlers, 'more hand-checks than handlers');
});
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const DEFAULT_PATH = fileURLToPath(new URL('./sectionRules.json', import.meta.url));
const SECTIONS = new Set(['produce', 'meat', 'seafood', 'eggs_dairy', 'bulk_pantry', 'frozen']);
const cache = new Map();
const str = (s) => typeof s === 'string' && s.trim() !== '';

// Reads once per path; missing file or bad JSON -> []. Output is exactly {section, rule, checks}.
export function loadSectionRules(path = DEFAULT_PATH) {
  if (cache.has(path)) return cache.get(path);
  let rules = [];
  try {
    const raw = JSON.parse(readFileSync(path, 'utf8'));
    const seen = new Set();
    for (const e of Array.isArray(raw) ? raw : []) {
      if (!e || !SECTIONS.has(e.section) || seen.has(e.section) || !str(e.rule)) continue;
      if (!Array.isArray(e.checks) || e.checks.length > 3 || !e.checks.every(str)) continue;
      seen.add(e.section);
      rules.push({ section: e.section, rule: e.rule, checks: [...e.checks] });
    }
  } catch {
    rules = [];
  }
  cache.set(path, rules);
  return rules;
}

